mapper.select:
SELECT a.id activityId,a.title,
  SUM(CASE WHEN s.status IN ('APPROVED','PROMOTED','COMPLETED') THEN 1 ELSE 0 END) successfulSignups,
  (SELECT COUNT(*) FROM activity_waitlist w WHERE w.activity_id=a.id AND w.deleted=0 AND w.status='WAITING') waitlistCount
FROM activity a LEFT JOIN activity_signup s ON s.activity_id=a.id AND s.deleted=0 AND s.created_at>=#{start} AND s.created_at<#{end}
WHERE a.deleted=0 GROUP BY a.id,a.title ORDER BY successfulSignups DESC,waitlistCount DESC,a.id DESC LIMIT #{limit}
